--   q[id]  = 名称|任务等级|地区|阵营(A联盟/H部落/空=不限)|奖励物品id,id
--   i[id]  = 名称|品质|物品等级|每秒伤害|速度|部位|类型|属性|图标名|是否装备
--   s[n]   = 系列名|最低等级|最高等级|地区|档位(按系列长度 S>=8/A>=5/B)|是否开门/史诗|步骤任务id,id
--   sn[id] = 系列步骤名（该步骤任务本身没有装备奖励、不在 q 表里时用它）
-- 逻辑层在 quest/QuestChains.lua（EVAL_QC_BULK_*）；界面只在「数据检索」Tab 用它。
